## ---- 01: Scheduled Principal Dollar-for-Dollar: A Numerical Example  (qmd line 159) --

amortize_simple <- function(B0, coupon_annual, n, SMM, MDR, horizon = 6) {
  c_m <- coupon_annual / 12
  pmt <- B0 * c_m / (1 - (1 + c_m)^(-n))
  B <- numeric(horizon + 1); B[1] <- B0
  I <- P <- VP <- D <- numeric(horizon)
  tau <- n
  for (t in seq_len(horizon)) {
    I[t]        <- B[t] * c_m
    psched      <- pmt - I[t]
    B_post      <- B[t] - psched
    VP[t]       <- B_post * SMM
    D[t]        <- B_post * MDR
    P[t]        <- psched * (1 - SMM - MDR)
    B[t + 1]    <- B[t] - P[t] - VP[t] - D[t]
    tau         <- tau - 1
  }
  data.frame(t = seq_len(horizon), begin = B[-(horizon+1)],
             I, P, VP, D, end = B[-1])
}

amortize_simple(500000, 0.075, 240, 0.004, 0.001)


## ---- 02: Level-Payment Formula  (qmd line 230) ---------------------------------------

level_pmt <- function(B0, coupon_annual, n_periods, k = 12) {
  c <- coupon_annual / k
  B0 * c / (1 - (1 + c)^(-n_periods))
}

level_pmt(1e6, 0.085, 300)        # 8052.27


## ---- 03: Closed-Form Amortization Schedule  (qmd line 241) ---------------------------

amort_schedule <- function(B0, coupon_annual, n_periods, k = 12) {
  c <- coupon_annual / k
  pmt <- level_pmt(B0, coupon_annual, n_periods, k)
  B <- numeric(n_periods + 1); B[1] <- B0
  I <- P <- numeric(n_periods)
  for (t in seq_len(n_periods)) {
    I[t] <- B[t] * c
    P[t] <- pmt - I[t]
    B[t + 1] <- B[t] - P[t]
  }
  data.frame(t = 1:n_periods, B_begin = B[-(n_periods+1)],
             pmt = pmt, I = I, P = P, B_end = B[-1])
}


## ---- 04: Variable-Rate Re-Amortization  (qmd line 259) -------------------------------

amortize_variable <- function(B0, prime_path, margin, n_periods,
                              SMM, MDR, k = 12) {
  B <- numeric(n_periods + 1); B[1] <- B0
  I <- P <- VP <- D <- numeric(n_periods)
  for (t in seq_len(n_periods)) {
    coupon <- (prime_path[t] + margin) / k
    pmt    <- B[t] * coupon / (1 - (1 + coupon)^(-(n_periods - t + 1)))
    psched <- pmt - B[t] * coupon
    B_post <- B[t] - psched
    VP[t]  <- B_post * SMM[t]
    D[t]   <- B_post * MDR[t]
    P[t]   <- psched * (1 - SMM[t] - MDR[t])
    I[t]   <- B[t] * coupon
    B[t + 1] <- B[t] - P[t] - VP[t] - D[t]
  }
  data.frame(t = 1:n_periods, B_begin = B[-(n_periods+1)],
             I, P, VP, D, B_end = B[-1])
}


## ---- 05: Day-Count Calculations  (qmd line 282) --------------------------------------

day_count_factor <- function(d_accr, basis = "30/360") {
  switch(basis,
    "30/360"   = d_accr / 360,
    "ACT/360"  = d_accr / 360,
    "ACT/365"  = d_accr / 365,
    "ACT/ACT"  = d_accr / 365.25
  )
}


## ---- 06: Balloon Loan  (qmd line 295) ------------------------------------------------

amortize_balloon <- function(B0, coupon, amort_term, balloon_term, k = 12) {
  pmt <- level_pmt(B0, coupon, amort_term, k)
  c <- coupon / k
  B_balloon <- B0 * (1 + c)^balloon_term -
               pmt * ((1 + c)^balloon_term - 1) / c
  list(pmt = pmt, balloon_payment = B_balloon)
}

amortize_balloon(1e6, 0.075, amort_term = 360, balloon_term = 120)


## ---- 07: Prepayment Penalty  (qmd line 309) ------------------------------------------

library(dplyr)   # case_when

standard_penalty <- function(months_seasoned) {
  case_when(
    months_seasoned <= 12 ~ 0.05,
    months_seasoned <= 24 ~ 0.03,
    months_seasoned <= 36 ~ 0.01,
    TRUE                  ~ 0.00
  )
}

# Penalty cashflow for whole-loan investor
penalty_cf <- function(VP, age) VP * standard_penalty(age)


